CREATE TABLE prodotti (id NUMBER(10) PRIMARY KEY, nome VARCHAR2(100), prezzo NUMBER(12,2), creato DATE, aggiornato TIMESTAMP, peso BINARY_DOUBLE, note CLOB);
INSERT INTO prodotti SELECT LEVEL, 'Prodotto ' || LEVEL || CASE WHEN MOD(LEVEL, 10) = 0 THEN ' città' END, LEVEL * 1.25, DATE '2023-01-01' + MOD(LEVEL, 500), TIMESTAMP '2024-01-01 00:00:00' + NUMTODSINTERVAL(LEVEL, 'SECOND'), CASE WHEN MOD(LEVEL, 3) = 0 THEN NULL ELSE LEVEL / 3 END, CASE WHEN MOD(LEVEL, 50) = 0 THEN 'nota lunga ' || LEVEL END FROM dual CONNECT BY LEVEL <= 50000;
COMMIT;
CREATE VIEW prodotti_cari AS SELECT nome, prezzo FROM prodotti WHERE prezzo > 60000;
EXIT;
